import java.util.Arrays;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
            int sum = 0;
                    for (int num : nums) {
                                sum += num;
                                        }

                                                // If total sum is not divisible by k, partition is impossible
                                                        if (sum % k != 0) {
                                                                    return false;
                                                                            }

                                                                                    int target = sum / k;
                                                                                            
                                                                                                    // Sort in ascending order, then iterate backwards to place larger elements first
                                                                                                            Arrays.sort(nums);
                                                                                                                    
                                                                                                                            // If the largest element exceeds the target, impossible to form valid subsets
                                                                                                                                    int n = nums.length;
                                                                                                                                            if (nums[n - 1] > target) {
                                                                                                                                                        return false;
                                                                                                                                                                }

                                                                                                                                                                        boolean[] used = new boolean[n];
                                                                                                                                                                                return backtrack(nums, used, k, 0, 0, n - 1, target);
                                                                                                                                                                                    }

                                                                                                                                                                                        private boolean backtrack(int[] nums, boolean[] used, int k, int currentSum, int count, int startIndex, int target) {
                                                                                                                                                                                                // Successfully formed k - 1 subsets, remaining elements will automatically sum to target
                                                                                                                                                                                                        if (count == k - 1) {
                                                                                                                                                                                                                    return true;
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                    // Current subset is full; start building the next subset
                                                                                                                                                                                                                                            if (currentSum == target) {
                                                                                                                                                                                                                                                        return backtrack(nums, used, k, 0, count + 1, nums.length - 1, target);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                        for (int i = startIndex; i >= 0; i--) {
                                                                                                                                                                                                                                                                                    // Skip already used elements or elements that exceed target
                                                                                                                                                                                                                                                                                                if (used[i] || currentSum + nums[i] > target) {
                                                                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                        // Mark and explore
                                                                                                                                                                                                                                                                                                                                                    used[i] = true;
                                                                                                                                                                                                                                                                                                                                                                if (backtrack(nums, used, k, currentSum + nums[i], count, i - 1, target)) {
                                                                                                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                        used[i] = false;

                                                                                                                                                                                                                                                                                                                                                                                                                    // Pruning: if current element cannot start a subset, no need to try identical or other starts
                                                                                                                                                                                                                                                                                                                                                                                                                                if (currentSum == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Skip duplicate values to avoid redundant branches
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    while (i > 0 && nums[i] == nums[i - 1]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    i--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }